import type { EngineInterface, Register } from 'claude-code'

const TOOL = 'mcp__clear-then__schedule'

// The prompt to submit after the next /clear; one at a time, the latest wins.
let pending: string | undefined

function clearAndSubmit($: EngineInterface, text: string) {
  pending = undefined
  $.ui.status(undefined)
  $.clock.after(50, async () => {
    await $.command.run({ command: 'clear', args: '' })
    await $.prompt.submit({ text, asUser: true })
  })
}

export const register: Register = on => {

  on('session.start', async ($, e, next) => {
    await $.command.register({
      name: 'clear-then',
      description: 'When the current turn ends, run /clear and submit the given prompt',
      argumentHint: '<prompt>',
    })
    await $.tool.register({
      name: 'schedule',
      description:
        'Schedules a fresh start: when your current turn ends, the session is cleared (/clear) and `prompt` is submitted as the first message of the new conversation. Use it when the user asks you to clear the session at the end of the work and continue with a given prompt (e.g. "create the task, then clear and say: do task TS-123"). The new conversation sees nothing from this one, so the prompt must be self-contained. Calling it again replaces the scheduled prompt; an empty prompt cancels it.',
      inputSchema: {
        type: 'object',
        properties: { prompt: { type: 'string', description: 'The prompt to submit after /clear' } },
        required: ['prompt'],
      },
      isDeferred: false,
    })
    return next(e)
  })

  // Typed by the person: a non-immediate command waits for the running turn to end,
  // so by the time it runs the work is done and the session is idle.
  on('command.run', { command: 'clear-then' }, async ($, e) => {
    const text = e.args.trim()
    if (text === '') return { text: 'Usage: /clear-then <prompt>' }
    clearAndSubmit($, text)
    return { text: `Clearing the session, then submitting: ${text}` }
  })

  // Called by Claude: remembered until the turn ends.
  on('tool.call', { tool: TOOL }, async ($, e) => {
    const text = String((e as { prompt?: unknown }).prompt ?? '').trim()
    if (text === '') {
      pending = undefined
      $.ui.status(undefined)
      return { result: 'Cancelled the scheduled clear.', text: 'Cancelled the scheduled clear.' }
    }
    pending = text
    $.ui.status(`clear-then: ${text.slice(0, 60)}`)
    const answer = `Scheduled: when this turn ends the session is cleared and this prompt is submitted: ${text}`
    return { result: answer, text: answer }
  })

  on('turn.complete', async ($, e, next) => {
    const done = await next(e)
    // Main loop only, and only a turn that finished normally: an interrupt keeps it pending.
    if (e.agentId === undefined && e.reason === 'answer' && pending !== undefined) clearAndSubmit($, pending)
    return done
  })
}

